  protected override void Initialize() {
    this.InitSpecialTokens((int)Tokens.error, (int)Tokens.EOF);
    this.InitStates(states);
    this.InitRules(rules);
    this.InitNonTerminals(nonTerms);
  }

  protected override void DoAction(int action)
  {
    switch (action)
    {
      case 2: // program -> task_list, optional_semicolon, END_OF_FILE
{
                  if (!is_unit_to_be_parsed) {
                      // �?�?еоб�?аз�?ем список зада�? в некий мод�?л�?/AST
                      var tasksBlock = parserTools.MakeTasksModule(ValueStack[ValueStack.Depth-3], CurrentLocationSpan);
                      root = tasksBlock; 
                  } 
                  else {
                      // �?сли �?айл па�?си�?ся как unit, аналоги�?но
                      // ...
                  }
              }
        break;
      case 3: // program -> stmt_list, optional_semicolon, END_OF_FILE
{
			if (!is_unit_to_be_parsed) {
				var stl = ValueStack[ValueStack.Depth-3].stn as statement_list;
				stl.left_logical_bracket = new token_info("");
				stl.right_logical_bracket = new token_info("");
				var bl = new block(new declarations(), stl, CurrentLocationSpan);
				root = CurrentSemanticValue.stn = NewProgramModule(null, null, new uses_list(), bl, ValueStack[ValueStack.Depth-2].ob, CurrentLocationSpan);
				root.source_context = bl.source_context;
			}
			else {
				var interface_part = new interface_node(new declarations(), new uses_list(), null, null);
				var initialization_part = new initfinal_part(null, ValueStack[ValueStack.Depth-3].stn as statement_list, null, null, null, CurrentLocationSpan);

				root = CurrentSemanticValue.stn = new unit_module(
					new unit_name(new ident(Path.GetFileNameWithoutExtension(parserTools.currentFileName)),
					UnitHeaderKeyword.Unit, CurrentLocationSpan), interface_part, null,
					initialization_part.initialization_sect,
					initialization_part.finalization_sect, null, CurrentLocationSpan);
			}

		}
        break;
      case 4: // task_list -> /* empty */
{ 
          // п�?с�?ой список
          CurrentSemanticValue = new List<syntax_tree_node>();
      }
        break;
      case 5: // task_list -> task_list, task_definition
{
          // добавляем о�?е�?едн�?�? зада�?�?
          var tasks = ValueStack[ValueStack.Depth-2] as List<syntax_tree_node>;
          tasks.Add(ValueStack[ValueStack.Depth-1]);
          CurrentSemanticValue = tasks;
      }
        break;
      case 6: // task_definition -> TASK, task_id, COLON, end_of_line, INDENT, InputSection, 
              //                    CheckSection, TestsSection, OutputSection, UNINDENT
{
          // Соби�?аем все 4 сек�?ии в один �?зел
          CurrentSemanticValue = new DSLTaskNode(ValueStack[ValueStack.Depth-9], ValueStack[ValueStack.Depth-6].ti, ValueStack[ValueStack.Depth-5], ValueStack[ValueStack.Depth-4], ValueStack[ValueStack.Depth-3], CurrentLocationSpan);
      }
        break;
      case 7: // task_id -> INTNUM
{ CurrentSemanticValue = ValueStack[ValueStack.Depth-1].ex; }
        break;
      case 8: // task_id -> ident
{ CurrentSemanticValue = ValueStack[ValueStack.Depth-1].id; }
        break;
      case 9: // InputSection -> INPUT, COLON, end_of_line, block
{
          // block -- э�?о stmt_list: можем писа�?�? var-об�?явления, CheckData(...) и п�?о�?ее
